/** Original176×223 GUI, source circle/thermometer/7-digit startup display and exact drag hit areas. */
public final class GasTurbineScreen extends LegacyContainerScreen<GasTurbineMenu> {
    private static final ResourceLocation TEXTURE=ResourceLocation.parse("hbm:textures/gui/generators/gui_turbinegas.png"),UTILITY=ResourceLocation.parse("hbm:textures/gui/gui_utility.png");
    private int yStart,slidStart,numberToDisplay,digitNumber,exponent;
    public GasTurbineScreen(GasTurbineMenu menu,Inventory player,Component title){super(menu,player,title,TEXTURE,176,223);}
    private GasTurbineBlockEntity machine(){return minecraft!=null&&minecraft.level!=null&&minecraft.level.getBlockEntity(menu.position) instanceof GasTurbineBlockEntity machine?machine:null;}
    @Override protected void renderLabels(GuiGraphics graphics,int x,int y){graphics.drawString(font,title,imageWidth/2-font.width(title)/2,6,4210752,false);graphics.drawString(font,playerInventoryTitle,8,129,4210752,false);}
    @Override protected void renderBg(GuiGraphics graphics,float partial,int x,int y){super.renderBg(graphics,partial,x,y);var machine=machine();if(machine==null)return;drawLegacyRegion(graphics,74,86,194,machine.autoMode?11:24,29,13);switch(machine.state){case 0->drawLegacyRegion(graphics,80,32,178,38,16,16);case -1->{drawLegacyRegion(graphics,80,32,194,38,16,16);if(numberToDisplay<8888888&&machine.counter<60){digitNumber++;if(digitNumber==9){digitNumber=1;exponent++;}numberToDisplay+=Math.pow(10,exponent);}if(machine.counter>50)numberToDisplay=0;digits(graphics,numberToDisplay);}case 1->{drawLegacyRegion(graphics,80,32,210,38,16,16);digits(graphics,20*machine.instantPowerOutput);}default->{}}
        drawLegacyRegion(graphics,36,97-machine.powerSliderPos,178,0,16,6);int stored=machine.getPowerExact().multiply(java.math.BigInteger.valueOf(142)).divide(java.math.BigInteger.valueOf(GasTurbineOperation.maxPower)).intValue();if(stored>0)drawLegacyRegion(graphics,26,109,0,223,stored,16);GasTurbineGauge.render(graphics,TEXTURE,leftPos+64,topPos+16,machine.rpm/100D);int heat=64*machine.temp/800;if(heat>0)drawLegacyRegion(graphics,136,92-heat,176,64-heat,2,heat);info(graphics,34,3);info(graphics,50,2);if(machine.tanks[0].getFill()<5000||machine.tanks[1].getFill()<1000)info(graphics,66,7);if(machine.tanks[0].getFill()==0||machine.tanks[1].getFill()==0)info(graphics,66,6);tank(graphics,machine.tanks[0],8,65,48);tank(graphics,machine.tanks[1],8,103,32);tank(graphics,machine.tanks[2],147,98,36);tank(graphics,machine.tanks[3],147,58,36);
    }
    private void digits(GuiGraphics graphics,int number){int[] digit=new int[7];for(int i=6;i>=0;i--){digit[i]=number%10;number/=10;drawLegacyRegion(graphics,65+i*7,71,194+digit[i]*5,0,5,11);}for(int i=0;i<6&&digit[i]==0;i++)drawLegacyRegion(graphics,65+i*7,71,244,0,5,11);}
    private void info(GuiGraphics graphics,int y,int type){graphics.blit(UTILITY,leftPos-16,topPos+y,type==3||type==7?24:8,type>=6?16:0,16,16,256,256);}
    private void tank(GuiGraphics graphics,FluidTank tank,int x,int bottom,int size){int height=tank.getFill()*size/tank.getMaxFill();if(height<=0)return;int color=tank.getTankType().getTint();graphics.flush();RenderSystem.enableBlend();RenderSystem.defaultBlendFunc();graphics.setColor((color>>16&255)/255F,(color>>8&255)/255F,(color&255)/255F,1);graphics.blit(tank.getTankType().getTexture(),leftPos+x,topPos+bottom-height,0,16-height,16,height,16,16);graphics.flush();graphics.setColor(1,1,1,1);RenderSystem.disableBlend();}
    private void keyLines(GuiGraphics graphics,String key,int x,int y){var lines=new ArrayList<Component>();for(var line:Component.translatable(key).getString().split("\\$"))lines.add(Component.literal(line));graphics.renderComponentTooltip(font,lines,x,y);}
    @Override public void render(GuiGraphics graphics,int x,int y,float partial){super.render(graphics,x,y,partial);var machine=machine();if(machine==null)return;if(legacyInfoHovered(x,y,26,108,142,16))graphics.renderTooltip(font,Component.literal(machine.getPowerExact()+" / "+GasTurbineOperation.maxPower+" HE"),x,y);if(legacyInfoHovered(x,y,36,36,16,66)){double consumption=GasTurbineOperation.fuelMaxCons.getOrDefault(machine.tanks[0].getTankType(),5D);graphics.renderTooltip(font,machine.state==1?Component.translatable("gui.hbm.gas_turbine.consumption",20*(consumption*.05+consumption*machine.throttle/100)):Component.translatable("gui.hbm.gas_turbine.offline"),x,y);}if(legacyInfoHovered(x,y,133,23,8,72))graphics.renderTooltip(font,Component.translatable("gui.hbm.gas_turbine.temperature",Math.max(20,machine.temp)),x,y);int[][] boxes={{8,16,48},{8,70,32},{147,61,36},{147,21,36}};for(int i=0;i<4;i++)if(legacyInfoHovered(x,y,boxes[i][0],boxes[i][1],16,boxes[i][2])){var lines=new ArrayList<Component>();var tank=machine.tanks[i];lines.add(tank.getTankType().displayName());lines.add(Component.literal(tank.getFill()+" / "+tank.getMaxFill()+" mB"));FluidInfo.append(tank.getTankType(),lines,hasShiftDown());graphics.renderComponentTooltip(font,lines,x,y);}if(legacyInfoHovered(x,y,-16,34,16,16))keyLines(graphics,"desc.gui.turbinegas.automode",leftPos-8,topPos+60);if(legacyInfoHovered(x,y,-16,50,16,16)){var lines=new ArrayList<Component>();lines.add(Component.translatable("desc.gui.turbinegas.fuels"));for(var type:HbmFluids.getInNiceOrder()){var trait=type.getTrait(FluidTraits.Combustible.class);if(trait!=null&&trait.getGrade()==FluidTraits.FuelGrade.GAS)lines.add(Component.literal("  ").append(type.displayName()));}graphics.renderComponentTooltip(font,lines,leftPos-8,topPos+60);}if((machine.tanks[0].getFill()<5000||machine.tanks[1].getFill()<1000)&&legacyInfoHovered(x,y,-16,66,16,16))keyLines(graphics,"desc.gui.turbinegas.warning",leftPos-8,topPos+60);}
    private void send(int action,int value){PacketDistributor.sendToServer(new GasTurbineControl(menu.position,action,value));}private void click(){minecraft.getSoundManager().play(SimpleSoundInstance.forUI(SoundEvents.UI_BUTTON_CLICK,1));}
    @Override public boolean mouseClicked(double x,double y,int button){boolean handled=super.mouseClicked(x,y,button);var machine=machine();if(machine==null)return handled;slidStart=machine.powerSliderPos;yStart=(int)y;if(Math.hypot(x-leftPos-88,y-topPos-40)<=8){if(machine.counter!=0&&machine.counter!=579)return handled;click();send(0,machine.state-1);handled=true;}if(machine.state==1&&x>leftPos+74&&x<=leftPos+103&&y>=topPos+86&&y<topPos+99){click();send(1,machine.autoMode?0:1);handled=true;}if(machine.state==1&&topPos+97-slidStart<=yStart&&topPos+103-slidStart>yStart&&x>leftPos+36&&x<=leftPos+52){send(1,0);click();handled=true;}return handled;}
    @Override public boolean mouseDragged(double x,double y,int button,double dx,double dy){boolean handled=super.mouseDragged(x,y,button,dx,dy);var machine=machine();if(machine!=null&&!machine.autoMode&&machine.state==1&&x>leftPos+36&&x<=leftPos+52&&y>topPos+37&&y<=topPos+103&&topPos+97-slidStart<=yStart&&topPos+103-slidStart>yStart){send(2,Mth.clamp(topPos+100-(int)y,0,60));return true;}return handled;}
}
